\node[below] at (O) {$O$};
\draw (L) -- (R);
\node[above] at (T) {$T$};
\coordinate (A) at (2.152,0.457);
\draw (T) -- (A);
\coordinate (C) at (1.414,1.685);
\coordinate (D) at (-1.994,-0.93);
\draw (A) -- (C);
\draw (T) -- (D);
\draw (A) -- (D);
\node[above] at (C) {$C$};
\node[left] at (D) {$D$};
\node[right] at (A) {$A$};
\pic[draw, "$39^{\circ}$", angle radius=0.6cm, angle eccentricity=2] {angle=A--T--R};
\pic[draw, "$?$", angle radius=0.5cm, angle eccentricity=2] {angle=T--C--A};
\pic[draw, "$?$", angle radius=0.45cm, angle eccentricity=2] {angle=A--D--T};
\end{tikzpicture}
[/tikz]
Which angle, $\angle TCA$ or $\angle TDA$, is equal to the marked tangent-chord angle?

